// MarshalJSON encodes whichever alternative is set (null if none).
func (u WebSearchResult) MarshalJSON() ([]byte, error) {
	switch {
	case u.String != nil:
		return json.Marshal(u.String, marshalOpts)
	case u.Object != nil:
		return json.Marshal(u.Object, marshalOpts)
	}
	return []byte("null"), nil
}

// UnmarshalJSON selects the alternative from the JSON value kind.
func (u *WebSearchResult) UnmarshalJSON(data []byte) error {
	*u = WebSearchResult{}
	switch k := jsonValueKind(data); k {
	case kindString:
		return json.Unmarshal(data, &u.String, jsonx.Foreign)
	case kindObject:
		return json.Unmarshal(data, &u.Object, jsonx.Foreign)
	case kindNull:
		return nil
	default:
		return fmt.Errorf("tools: cannot decode JSON %s into WebSearchResult", k)
	}
}

